import{_ as e,o as s,c as p,a2 as o}from"./chunks/framework.BXzK3EA4.js";const a="/assets/d8f035b721c80ce7.DRQI8GYw.png",d="/assets/785b236bb9362332.1GkERREd.png",k=JSON.parse('{"title":"物理服务器检查磁盘健康状态","description":"","frontmatter":{"title":"物理服务器检查磁盘健康状态"},"headers":[],"relativePath":"ops-knowledge-base/dedicated-server/check-disk-health.md","filePath":"ops-knowledge-base/dedicated-server/check-disk-health.md","lastUpdated":1788259091000}'),n={name:"ops-knowledge-base/dedicated-server/check-disk-health.md"};function r(l,t,c,i,m,u){return s(),p("div",null,[...t[0]||(t[0]=[o('<p>Windows系统</p><p>Windows 操作系统自带了磁盘检测和修复工具，叫做 &quot;磁盘检查&quot;（Check Disk）。它可以扫描并尝试修复文件系统中的错误、坏道等问题。</p><p>以下是使用磁盘检查工具的步骤：</p><p>1.打开 &quot;文件资源管理器&quot; （快捷键：Win + E）</p><p>2.选中需要检测的磁盘，右击后选择 &quot;属性&quot;</p><p><img src="'+a+'" alt=""></p><p>3.在 &quot;工具&quot; 选项卡下，点击 &quot;检查&quot; 按钮。</p><p><img src="'+d+'" alt=""></p><p>4.如果该磁盘正在被使用，你会看到一个提示框，询问你是否想要计划下次启动时进行检查。如果你想立即检查，请单击 &quot;立即检查&quot; 按钮。否则，选择 &quot;计划磁盘检查&quot; 并选择适当的选项。</p><p>5.系统会开始扫描和修复该磁盘上的问题。完成后，会显示扫描结果。</p><p>除此之外，还有一些第三方的磁盘检测软件，比如 CrystalDiskInfo、HD Tune、Victoria 等等。这些软件功能更加强大，可以提供更多的磁盘状态信息和诊断报告。</p><p>Linux系统</p><p>Linux可以通过命令工具查看</p><p>smartmontools：这是一个命令行工具集，包括 smartctl 和 smartd。smartctl 可以检查硬盘的 SMART 属性并报告任何问题，而 smartd 则可以在后台运行并监控磁盘状态。</p><p>CentOS：</p><p>yum -y install smartmontools &amp;&amp; smartctl --all /dev/nvme0n1 #/dev/* 具体名称请运行 sudo fdisk -l 查看</p><p>Ubuntu：</p><p>sudo apt install smartmontools &amp;&amp; sudo smartctl --all /dev/nvme0n1 #/dev/* 具体名称请运行 sudo fdisk -l 查看</p>',18)])])}const h=e(n,[["render",r]]);export{k as __pageData,h as default};
